import * as React from "react";
import { cx } from "./cx";

export interface ToastOptions {
  description?: React.ReactNode;
}

interface ToastItem {
  id: number;
  title: React.ReactNode;
  description?: React.ReactNode;
}

let nextId = 1;
const listeners = new Set<(item: ToastItem) => void>();

/** Fire a toast from anywhere; a mounted <Toaster /> renders it. */
export function toast(title: React.ReactNode, options?: ToastOptions): void {
  const item: ToastItem = { id: nextId++, title, description: options?.description };
  listeners.forEach((listener) => listener(item));
}

export interface ToasterProps extends React.HTMLAttributes<HTMLDivElement> {
  /** How long a toast stays, in milliseconds. */
  duration?: number;
}

export function Toaster({ duration = 4000, className, ...props }: ToasterProps) {
  const [items, setItems] = React.useState<ToastItem[]>([]);

  React.useEffect(() => {
    const add = (item: ToastItem) => {
      setItems((current) => [...current, item]);
      setTimeout(() => {
        setItems((current) => current.filter((i) => i.id !== item.id));
      }, duration);
    };
    listeners.add(add);
    return () => {
      listeners.delete(add);
    };
  }, [duration]);

  return (
    <div className={cx("rs-toasts", className)} role="status" aria-live="polite" {...props}>
      {items.map((item) => (
        <div key={item.id} className="rs-toast">
          <div>
            <span className="rs-toast-title">{item.title}</span>
            {item.description != null && <p className="rs-toast-body">{item.description}</p>}
          </div>
        </div>
      ))}
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Toast: quiet confirmations, bottom right, announced politely ── */
.rs-toasts{position:fixed;bottom:20px;right:20px;z-index:300;display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.rs-toast{display:flex;align-items:flex-start;gap:10px;background:var(--bg);border:1px solid var(--divider);border-radius:var(--radius);box-shadow:0 8px 24px rgba(0,0,0,0.06);padding:10px 14px;max-width:340px;animation:rsToastIn var(--duration-confirm) var(--ease)}
.rs-toast-title{display:block;font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-toast-body{font-size:12.5px;line-height:1.5;letter-spacing:-.01em;color:var(--text-secondary);margin:1px 0 0}
@keyframes rsToastIn{from{opacity:0}to{opacity:1}}
@media(prefers-reduced-motion:reduce){.rs-toast{animation:none}}
